/* Generated by scripts/build.mjs from the shared legal page terms.html. */
/* Apply the saved theme before first paint. Same key as the home page. */
(function () {
  try {
    var t = localStorage.getItem('aa-theme');
    if (t === 'light' || t === 'dark') document.documentElement.setAttribute('data-theme', t);
  } catch (e) {}
})();
